def modal_footer(
    submit_label: str,
    on_cancel: EventType[()],
    *,
    disabled: bool | rx.Var[bool] = False,
    loading: bool | rx.Var[bool] = False,
) -> rx.Component:
    """Sticky footer with cancel + submit buttons for modals/drawers."""
    return mn.group(
        mn.button(
            "Abbrechen",
            variant="subtle",
            on_click=on_cancel,
